import type { Merger } from "./callback";
export function recur<T>(base: T, defaults: any, merger?: Merger): T {
 const result = Object.assign({}, defaults);
 for (const key in base) { const value: unknown = base[key]; result[key] = recur(value, result[key], merger); }
 return result;
}

declare function consume<T>(callback: <U>(value: U) => T): T;
declare function value<U>(input: U): string;
export const result = consume(value);

declare function consume<T>(value: T, callback: <U>(input: U) => T): T;
declare function numeric<U>(input: U): number;
export const result = consume("s", numeric);
